// Assemble the day file from the three report endpoints.
// Each endpoint may return any JSON shape; we pass them through verbatim
// so the Auditor reasons over exactly what your systems said.
const bookings = $('Fetch Yesterday Bookings').all().map(i => i.json);
const finance  = $('Fetch Yesterday Invoices').all().map(i => i.json);
const threads  = $('Fetch Unanswered Threads').all().map(i => i.json);
return [{ json: {
  chatInput: `NIGHT AUDIT — raw day file (JSON):\nBOOKINGS: ${JSON.stringify(bookings)}\nFINANCE: ${JSON.stringify(finance)}\nUNANSWERED_THREADS: ${JSON.stringify(threads)}`
} }];
